const fs=require('fs'),path=require('path'),{execSync}=require('child_process');
const files={"frontend/src/components/ui/NavLevel.tsx":"\"use client\";\n// Progressive nav level detection\n// Returns 0-4 based on how far the user has progressed\nimport { useQuery } from \"@tanstack/react-query\";\nimport { useAuthStore } from \"../../store/auth.store\";\nimport { api } from \"../../lib/api\";\n\nexport interface NavLevel {\n  level: number; // 0=new, 1=has products, 2=has orders, 3=growing, 4=advanced\n  productCount: number;\n  orderCount: number;\n  hasPaystack: boolean;\n  label: string;\n}\n\nexport function useNavLevel(): NavLevel {\n  const user   = useAuthStore(s => s.user);\n  const store  = user?.stores?.[0];\n\n  const { data } = useQuery({\n    queryKey:  [\"nav-level\", store?.id],\n    queryFn:   () => api.get(`/nav-level/${store?.id}`).then(r => r.data.data),\n    enabled:   !!store?.id,\n    staleTime: 300000,\n    retry:     false,\n  });\n\n  const productCount = data?.productCount ?? 0;\n  const orderCount   = data?.orderCount   ?? 0;\n  const hasPaystack  = data?.hasPaystack  ?? false;\n\n  let level = 0;\n  if (productCount >= 1)  level = 1;\n  if (orderCount  >= 1)   level = 2;\n  if (orderCount  >= 10)  level = 3;\n  if (orderCount  >= 50)  level = 4;\n\n  const labels = [\"Just starting\", \"Getting set up\", \"First orders in\", \"Growing fast\", \"Power seller\"];\n\n  return { level, productCount, orderCount, hasPaystack, label: labels[level] };\n}\n\n// Which nav groups to show at each level\nexport function getVisibleGroups(level: number): string[] {\n  if (level === 0) return [\"top\", \"store-core\", \"account\"];\n  if (level === 1) return [\"top\", \"store\", \"sales-core\", \"account\"];\n  if (level === 2) return [\"top\", \"store\", \"sales\", \"marketing-core\", \"account\"];\n  if (level === 3) return [\"top\", \"store\", \"sales\", \"marketing\", \"studio\", \"account\"];\n  return [\"top\", \"store\", \"sales\", \"marketing\", \"studio\", \"intelligence\", \"tools\", \"developers\", \"account\"];\n}\n","frontend/src/app/dashboard/billing/page.tsx":"\"use client\";\n\n// Path: frontend/src/app/dashboard/billing/page.tsx\n\nimport { useState } from \"react\";\nimport { motion } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { Check, Zap, Crown, ArrowUpRight, CreditCard, Receipt, ChevronRight, Shield, Sparkles } from \"lucide-react\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { useMutation } from \"@tanstack/react-query\";\nimport { api } from \"../../../lib/api\";\nimport toast from \"react-hot-toast\";\n\nconst V = { v900: \"#1A0D3D\", v700: \"#3D1C8A\", v600: \"#5428C8\", v500: \"#6B35E8\", v400: \"#8B5CF6\", v300: \"#A78BFA\", v200: \"#C4B5FD\", fuchsia: \"#C026D3\" };\nconst T = {\n  dark:  { card: \"#181230\", border: \"rgba(255,255,255,0.06)\", text: \"#fff\", muted: \"rgba(255,255,255,0.38)\", faint: \"rgba(255,255,255,0.04)\" },\n  light: { card: \"#fff\",    border: \"rgba(15,5,32,0.07)\",    text: \"#0D0918\", muted: \"rgba(13,9,24,0.45)\", faint: \"rgba(15,5,32,0.03)\" },\n};\n\nconst PLANS = [\n  {\n    id: \"FREE\", name: \"Free\", price: { ngn: 0, gbp: 0, usd: 0 },\n    icon: Sparkles, color: \"#6B7280\",\n    features: [\"1 store\", \"20 products\", \"KIRO 10 msgs/day\", \"Basic analytics\", \"2% transaction fee\", \"Community support\"],\n    limit: true,\n  },\n  {\n    id: \"GROWTH\", name: \"Growth\", price: { ngn: 9500, gbp: 12, usd: 15 },\n    icon: Zap, color: V.v400,\n    features: [\"1 store\", \"Unlimited products\", \"Full KIRO access\", \"Advanced analytics\", \"Custom domain\", \"1.5% transaction fee\", \"Email support 24hr\", \"Coupons & flash sales\", \"Abandoned cart recovery\"],\n    popular: true,\n  },\n  {\n    id: \"PRO\", name: \"Pro\", price: { ngn: 25000, gbp: 35, usd: 45 },\n    icon: Crown, color: \"#F59E0B\",\n    features: [\"Unlimited stores\", \"Everything in Growth\", \"KIRO Pro intelligence\", \"WhatsApp commerce bot\", \"1% transaction fee\", \"Email campaigns\", \"Loyalty programme\", \"3 staff accounts\", \"API access\", \"Priority support 2hr\"],\n  },\n];\n\nconst CURRENCY_LABELS: Record<string, string> = { ngn: \"₦\", gbp: \"£\", usd: \"$\" };\n\nexport default function BillingPage() {\n  const { theme } = useTheme();\n  const t = theme === \"dark\" ? T.dark : T.light;\n  const { user } = useAuthStore();\n  const [billing, setBilling] = useState<\"monthly\" | \"annual\">(\"monthly\");\n  const [currency, setCurrency] = useState<\"ngn\" | \"gbp\" | \"usd\">(\"ngn\");\n  const currentPlan = user?.subscription?.plan || \"FREE\";\n\n  const upgradeMut = useMutation({\n    mutationFn: async (planId: string) => {\n      const price = PLANS.find(p => p.id === planId)?.price[currency] || 0;\n      const amount = billing === \"annual\" ? Math.round(price * 10) : price; // 10 months for annual (2 free)\n      return api.post(\"/billing/upgrade\", { plan: planId, currency, billing, amount });\n    },\n    onSuccess: (res) => {\n      const url = res.data?.data?.authorizationUrl || res.data?.data?.url;\n      if (url) { window.location.href = url; }\n      else { toast.success(\"Plan updated!\"); }\n    },\n    onError: (e: any) => toast.error(e.response?.data?.message || \"Upgrade failed - backend offline\"),\n  });\n\n  const handleUpgrade = (planId: string) => {\n    if (planId === \"FREE\") return;\n    if (planId === currentPlan) { toast.success(\"You are already on this plan\"); return; }\n    const plan = PLANS.find(p => p.id === planId);\n    const price = plan?.price[currency] || 0;\n    const msg = billing === \"annual\"\n      ? `Upgrade to ${plan?.name} — ${CURRENCY_LABELS[currency]}${(price * 10).toLocaleString()}/year (2 months free)`\n      : `Upgrade to ${plan?.name} — ${CURRENCY_LABELS[currency]}${price.toLocaleString()}/month`;\n    toast.loading(msg, { duration: 2000 });\n    setTimeout(() => upgradeMut.mutate(planId), 400);\n  };\n\n  return (\n    <div style={{ maxWidth: 1100, margin: \"0 auto\" }}>\n      {/* Header */}\n      <motion.div initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }}\n        style={{ display: \"flex\", alignItems: \"flex-start\", justifyContent: \"space-between\", gap: 16, marginBottom: 32 }}>\n        <div>\n          <h1 style={{ fontSize: 22, fontWeight: 800, letterSpacing: \"-0.03em\", color: t.text }}>Billing & Plans</h1>\n          <p style={{ fontSize: 13, color: t.muted, marginTop: 4 }}>Manage your subscription and payment details</p>\n        </div>\n        <div style={{ display: \"flex\", gap: 8 }}>\n          <button style={{ display: \"flex\", alignItems: \"center\", gap: 6, padding: \"9px 14px\", borderRadius: 11, border: `1px solid ${t.border}`, background: \"transparent\", cursor: \"pointer\", fontSize: 13, color: t.muted }}>\n            <Receipt size={13} /> View Invoices\n          </button>\n        </div>\n      </motion.div>\n\n      {/* Current plan banner */}\n      <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}\n        style={{ padding: \"18px 22px\", borderRadius: 16, marginBottom: 28, background: \"rgba(107,53,232,0.08)\", border: \"1px solid rgba(107,53,232,0.2)\", display: \"flex\", alignItems: \"center\", gap: 14 }}>\n        <div style={{ width: 40, height: 40, borderRadius: 12, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", background: `linear-gradient(145deg, ${V.v500}, ${V.v900})`, boxShadow: \"0 4px 14px rgba(107,53,232,0.3)\" }}>\n          <Zap size={18} color=\"white\" />\n        </div>\n        <div style={{ flex: 1 }}>\n          <div style={{ fontSize: 14, fontWeight: 700, color: t.text }}>You're on the <span style={{ color: V.v300 }}>{currentPlan}</span> plan</div>\n          <div style={{ fontSize: 12, color: t.muted, marginTop: 2 }}>Upgrade anytime. No contracts. Cancel anytime.</div>\n        </div>\n        <div style={{ display: \"flex\", alignItems: \"center\", gap: 8 }}>\n          <Shield size={13} color={V.v400} />\n          <span style={{ fontSize: 12, color: V.v400 }}>Secured by Paystack</span>\n        </div>\n      </motion.div>\n\n      {/* Billing toggle + currency */}\n      <div className=\"flex flex-wrap items-center justify-center gap-3 mb-7\" style={{}}>\n        <div style={{ display: \"flex\", padding: 3, borderRadius: 12, background: t.card, border: `1px solid ${t.border}` }}>\n          {([\"monthly\", \"annual\"] as const).map(b => (\n            <button key={b} onClick={() => setBilling(b)}\n              style={{ padding: \"7px 20px\", borderRadius: 10, border: \"none\", cursor: \"pointer\", fontSize: 13, fontWeight: billing === b ? 600 : 400, background: billing === b ? (theme === \"dark\" ? \"rgba(107,53,232,0.25)\" : \"rgba(107,53,232,0.12)\") : \"transparent\", color: billing === b ? (theme === \"dark\" ? V.v200 : V.v600) : t.muted, transition: \"all 0.15s\" }}>\n              {b === \"monthly\" ? \"Monthly\" : \"Annual\"}{b === \"annual\" && <span style={{ marginLeft: 6, fontSize: 10, fontWeight: 700, padding: \"1px 5px\", borderRadius: 4, background: \"rgba(16,185,129,0.2)\", color: \"#10B981\" }}>-17%</span>}\n            </button>\n          ))}\n        </div>\n        <div style={{ display: \"flex\", padding: 3, borderRadius: 12, background: t.card, border: `1px solid ${t.border}` }}>\n          {([\"ngn\", \"gbp\", \"usd\"] as const).map(c => (\n            <button key={c} onClick={() => setCurrency(c)}\n              style={{ padding: \"7px 14px\", borderRadius: 10, border: \"none\", cursor: \"pointer\", fontSize: 13, fontWeight: currency === c ? 600 : 400, background: currency === c ? (theme === \"dark\" ? \"rgba(107,53,232,0.25)\" : \"rgba(107,53,232,0.12)\") : \"transparent\", color: currency === c ? (theme === \"dark\" ? V.v200 : V.v600) : t.muted, transition: \"all 0.15s\" }}>\n              {CURRENCY_LABELS[c]}{c.toUpperCase()}\n            </button>\n          ))}\n        </div>\n      </div>\n\n      {/* Plan cards */}\n      <div className=\"grid grid-cols-1 md:grid-cols-3 gap-4 mb-8\" style={{}}>\n        {PLANS.map((plan, i) => {\n          const Icon = plan.icon;\n          const isCurrent = currentPlan === plan.id;\n          const price = billing === \"annual\" ? Math.round(plan.price[currency] * 10) : plan.price[currency];\n          const isPopular = plan.popular;\n\n          return (\n            <motion.div key={plan.id} initial={{ opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.1 }}\n              style={{ padding: 24, borderRadius: 20, position: \"relative\", overflow: \"hidden\", background: isPopular ? `linear-gradient(145deg, ${V.v900} 0%, #110D22 100%)` : t.card, border: `1px solid ${isPopular ? \"rgba(107,53,232,0.4)\" : isCurrent ? \"rgba(107,53,232,0.25)\" : t.border}`, boxShadow: isPopular ? \"0 8px 32px rgba(107,53,232,0.25)\" : theme === \"light\" ? \"0 1px 3px rgba(15,5,32,0.04), 0 4px 20px rgba(15,5,32,0.03)\" : \"none\" }}>\n\n              {/* Glow for popular */}\n              {isPopular && <div style={{ position: \"absolute\", top: -60, right: -60, width: 200, height: 200, borderRadius: \"50%\", background: \"radial-gradient(circle, rgba(107,53,232,0.2) 0%, transparent 70%)\", pointerEvents: \"none\" }} />}\n\n              {/* Popular badge */}\n              {isPopular && (\n                <div style={{ position: \"absolute\", top: 14, right: 14, fontFamily: \"'Syncopate', sans-serif\", fontSize: 7.5, fontWeight: 700, letterSpacing: \"0.1em\", padding: \"4px 8px\", borderRadius: 6, background: `linear-gradient(135deg, ${V.v500}, ${V.fuchsia})`, color: \"white\" }}>POPULAR</div>\n              )}\n\n              {/* Current badge */}\n              {isCurrent && !isPopular && (\n                <div style={{ position: \"absolute\", top: 14, right: 14, fontFamily: \"'Syncopate', sans-serif\", fontSize: 7.5, fontWeight: 700, letterSpacing: \"0.1em\", padding: \"4px 8px\", borderRadius: 6, background: \"rgba(16,185,129,0.15)\", color: \"#10B981\", border: \"1px solid rgba(16,185,129,0.25)\" }}>CURRENT</div>\n              )}\n\n              {/* Plan icon */}\n              <div style={{ width: 44, height: 44, borderRadius: 14, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", marginBottom: 16, background: `${plan.color}20`, border: `1px solid ${plan.color}30` }}>\n                <Icon size={20} color={plan.color} />\n              </div>\n\n              <div style={{ fontFamily: \"'Syncopate', sans-serif\", fontSize: 11, fontWeight: 700, letterSpacing: \"0.1em\", color: plan.color, marginBottom: 6 }}>{plan.name.toUpperCase()}</div>\n\n              <div style={{ marginBottom: 20 }}>\n                <span style={{ fontSize: 32, fontWeight: 800, letterSpacing: \"-0.04em\", color: isPopular ? \"#fff\" : t.text }}>\n                  {CURRENCY_LABELS[currency]}{price === 0 ? \"0\" : price.toLocaleString()}\n                </span>\n                {price > 0 && <span style={{ fontSize: 13, color: isPopular ? \"rgba(255,255,255,0.45)\" : t.muted }}>/mo</span>}\n                {price === 0 && <span style={{ fontSize: 13, color: isPopular ? \"rgba(255,255,255,0.45)\" : t.muted }}> forever</span>}\n                {billing === \"annual\" && price > 0 && <div style={{ fontSize: 11, color: \"#10B981\", marginTop: 3 }}>Billed annually · 2 months free</div>}\n              </div>\n\n              {/* CTA */}\n              <button\n                disabled={isCurrent || upgradeMut.isPending}\n                onClick={() => !isCurrent && handleUpgrade(plan.id)}\n                style={{ width: \"100%\", padding: \"11px\", borderRadius: 12, border: isCurrent ? `1px solid ${t.border}` : \"none\", cursor: isCurrent ? \"default\" : \"pointer\", fontSize: 13, fontWeight: 700, marginBottom: 20, background: isCurrent ? \"transparent\" : isPopular ? `linear-gradient(135deg, ${V.v500}, ${V.v700})` : `${plan.color}15`, color: isCurrent ? t.muted : isPopular ? \"white\" : plan.color, boxShadow: isPopular && !isCurrent ? \"0 4px 16px rgba(107,53,232,0.35)\" : \"none\", transition: \"all 0.15s\", opacity: upgradeMut.isPending ? 0.7 : 1 }}>\n                {upgradeMut.isPending && upgradeMut.variables === plan.id ? \"Opening Paystack...\" : isCurrent ? \"Current Plan\" : plan.id === \"FREE\" ? \"Downgrade\" : `Upgrade to ${plan.name}`}\n              </button>\n\n              {/* Features */}\n              <div style={{ display: \"flex\", flexDirection: \"column\", gap: 8 }}>\n                {plan.features.map(f => (\n                  <div key={f} style={{ display: \"flex\", alignItems: \"center\", gap: 8 }}>\n                    <div style={{ width: 16, height: 16, borderRadius: \"50%\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\", background: `${plan.color}20`, flexShrink: 0 }}>\n                      <Check size={9} color={plan.color} />\n                    </div>\n                    <span style={{ fontSize: 12, color: isPopular ? \"rgba(255,255,255,0.7)\" : t.muted }}>{f}</span>\n                  </div>\n                ))}\n              </div>\n            </motion.div>\n          );\n        })}\n      </div>\n\n      {/* Payment method */}\n      <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.4 }}\n        style={{ padding: 20, borderRadius: 16, background: t.card, border: `1px solid ${t.border}`, display: \"flex\", alignItems: \"center\", gap: 14 }}>\n        <div style={{ width: 40, height: 40, borderRadius: 12, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", background: t.faint, border: `1px solid ${t.border}` }}>\n          <CreditCard size={18} color={t.muted} />\n        </div>\n        <div style={{ flex: 1 }}>\n          <div style={{ fontSize: 13, fontWeight: 600, color: t.text }}>No payment method added</div>\n          <div style={{ fontSize: 12, color: t.muted, marginTop: 2 }}>Add a card or bank account to upgrade your plan</div>\n        </div>\n        <button style={{ display: \"flex\", alignItems: \"center\", gap: 6, padding: \"8px 16px\", borderRadius: 10, border: \"none\", cursor: \"pointer\", background: `linear-gradient(135deg, ${V.v500}, ${V.v700})`, color: \"white\", fontSize: 13, fontWeight: 600, boxShadow: \"0 4px 12px rgba(107,53,232,0.3)\" }}>\n          Add Payment Method <ChevronRight size={13} />\n        </button>\n      </motion.div>\n    </div>\n  );\n}\n","frontend/src/hooks/useSessionRestore.ts":"\"use client\";\n// ============================================================\n// Session Restore Hook\n// Path: frontend/src/hooks/useSessionRestore.ts\n//\n// On every page load, tries to restore session from cookie.\n// User stays logged in even after server restart.\n// ============================================================\nimport { useEffect, useRef } from \"react\";\nimport { useAuthStore }      from \"@/store/auth.store\";\nimport { api }               from \"@/lib/api\";\n\nexport function useSessionRestore() {\n  const { user, accessToken, setUser, setAccessToken, setLoading, setHydrated } = useAuthStore();\n  const didRestore = useRef(false);\n\n  useEffect(() => {\n    if (didRestore.current) return;\n    didRestore.current = true;\n\n    const restore = async () => {\n      // Already have a valid access token in memory - no need to restore\n      if (accessToken) {\n        setHydrated(true);\n        return;\n      }\n\n      // Try to restore from httpOnly cookie\n      // If server is restarted, cookie still exists → restores session\n      try {\n        setLoading(true);\n        const res = await api.get(\"/auth/me\");\n        if (res.data.success) {\n          const { accessToken: newToken, user: restoredUser } = res.data.data;\n          setAccessToken(newToken);\n          setUser(restoredUser);\n        }\n      } catch {\n        // No valid session - user needs to log in\n        // Don't redirect - let each page decide what to do\n      } finally {\n        setLoading(false);\n        setHydrated(true);\n      }\n    };\n\n    restore();\n  }, []);\n}\n\n","frontend/tsconfig.json":"{\n  \"compilerOptions\": {\n    \"target\": \"es2017\",\n    \"lib\": [\n      \"dom\",\n      \"dom.iterable\",\n      \"esnext\"\n    ],\n    \"allowJs\": true,\n    \"skipLibCheck\": true,\n    \"strict\": true,\n    \"noEmit\": true,\n    \"esModuleInterop\": true,\n    \"module\": \"esnext\",\n    \"moduleResolution\": \"node\",\n    \"resolveJsonModule\": true,\n    \"isolatedModules\": true,\n    \"jsx\": \"preserve\",\n    \"incremental\": true,\n    \"plugins\": [\n      {\n        \"name\": \"next\"\n      }\n    ],\n    \"paths\": {\n      \"@/*\": [\n        \"./src/*\"\n      ]\n    },\n    \"baseUrl\": \".\"\n  },\n  \"include\": [\n    \"next-env.d.ts\",\n    \"**/*.ts\",\n    \"**/*.tsx\",\n    \".next/types/**/*.ts\"\n  ],\n  \"exclude\": [\n    \"node_modules\"\n  ]\n}","backend/src/app.ts":"import \"express-async-errors\";\n\nimport express, { Request, Response, NextFunction } from \"express\";\nimport cors from \"cors\";\nimport helmet from \"helmet\";\nimport compression from \"compression\";\nimport morgan from \"morgan\";\nimport cookieParser from \"cookie-parser\";\nimport path from \"path\";\n\n// Middleware\nimport { globalRateLimiter } from \"./middleware/rateLimiter\";\nimport { errorHandler } from \"./middleware/errorHandler\";\nimport { notFound } from \"./middleware/notFound\";\nimport { requestLogger } from \"./middleware/requestLogger\";\n\n// Core Routes\nimport authRefreshRoutes from \"./routes/auth.refresh.routes\";\nimport authRoutes        from \"./routes/auth.routes\";\nimport storeRoutes       from \"./routes/store.routes\";\nimport productRoutes     from \"./routes/product.routes\";\nimport orderRoutes       from \"./routes/order.routes\";\nimport paymentRoutes     from \"./routes/payment.routes\";\nimport customerRoutes    from \"./routes/customer.routes\";\nimport adminRoutes       from \"./routes/admin.routes\";\nimport analyticsRoutes   from \"./routes/analytics.routes\";\nimport uploadRoutes      from \"./routes/upload.routes\";\nimport supportRoutes     from \"./routes/support.routes\";\nimport notificationRoutes from \"./routes/notification.routes\";\nimport couponRoutes      from \"./routes/coupon.routes\";\nimport discountRoutes    from \"./routes/discount.routes\";\nimport affiliateRoutes   from \"./routes/affiliate.routes\";\nimport aiRoutes          from \"./routes/ai.routes\";\nimport pushRoutes        from \"./routes/push.routes\";\nimport shippingRoutes    from \"./routes/shipping.routes\";\nimport reviewRoutes      from \"./routes/review.routes\";\nimport invoiceRoutes     from \"./routes/invoice.routes\";\nimport emailRoutes       from \"./routes/email.routes\";\nimport upsellRoutes      from \"./routes/upsell.routes\";\nimport abandonedCartRoutes from \"./routes/abandonedCart.routes\";\nimport notifSettingsRoutes from \"./routes/notificationSettings.routes\";\nimport currencyRoutes      from \"./routes/currency.routes\";\nimport supplierRoutes      from \"./routes/supplier.routes\";\nimport refundRoutes        from \"./routes/refund.routes\";\nimport giftCardRoutes      from \"./routes/giftCard.routes\";\nimport customerAccountRoutes from \"./routes/customerAccount.routes\";\nimport funnelRoutes        from \"./routes/funnel.routes\";\nimport apiKeyRoutes        from \"./routes/apiKey.routes\";\nimport webhookRoutes       from \"./routes/webhook.routes\";\nimport returnsRoutes       from \"./routes/returns.routes\";\nimport twoFARoutes         from \"./routes/twoFA.routes\";\nimport productSubscriptionRoutes from \"./routes/productSubscription.routes\";\nimport onboardingRoutes  from \"./routes/onboarding.routes\";\nimport milestoneRoutes   from \"./routes/milestone.routes\";\nimport contactRoutes     from \"./routes/contact.routes\";\nimport bundleRoutes      from \"./routes/bundle.routes\";\nimport groupBuyRoutes    from \"./routes/groupbuy.routes\";\nimport referralRoutes    from \"./routes/referral.routes\";\nimport navLevelRoutes    from \"./routes/navlevel.routes\";\nimport reportsRoutes     from \"./routes/reports.routes\";\nimport waitlistRoutes      from \"./routes/waitlist.routes\";\n\n// KAI CORE\nimport kaiRoutes from \"./routes/kai.routes\";\n\n// KAI EXPANSIONS\nimport kaiPowerRoutes from \"./routes/kai.power.routes\";\nimport featuresRoutes from \"./routes/features.routes\";\nimport loyaltyRoutes from \"./routes/loyalty.routes\";\nimport superchargeRoutes from \"./routes/supercharge.routes\";\nimport kaiAgentRoutes from \"./routes/kai.agent.routes\";\nimport themeRoutes from \"./routes/theme.routes\";\n\n// Controllers (Advanced AI + Automation)\nimport productIntelRoutes from \"./controllers/product.intel.controller\";\nimport intelRoutes from \"./controllers/kai.intelligence.controller\";\nimport fulfillmentRoutes from \"./controllers/fulfillment.controller\";\n\nconst app = express();\n\n// TRUST PROXY\nif (process.env.NODE_ENV === \"production\") {\n  app.set(\"trust proxy\", 1);\n}\n\n// SECURITY\napp.use(helmet({\n  crossOriginResourcePolicy: { policy: \"cross-origin\" },\n  contentSecurityPolicy: {\n    directives: {\n      defaultSrc: [\"'self'\"],\n      scriptSrc: [\"'self'\", \"https://js.stripe.com\"],\n      frameSrc: [\"'self'\", \"https://js.stripe.com\"],\n      connectSrc: [\"'self'\", \"https://api.stripe.com\"],\n      imgSrc: [\"'self'\", \"data:\", \"https:\"],\n      styleSrc: [\"'self'\", \"'unsafe-inline'\"],\n    },\n  },\n}));\n\n// CORS\nconst allowedOrigins = [\n  process.env.FRONTEND_URL || \"http://localhost:3000\",\n  \"http://localhost:3000\",\n  \"https://dropos-frontend1.vercel.app\",\n  \"https://droposhq.com\",\n  \"https://www.droposhq.com\",\n].filter(Boolean);\n\napp.use(cors({\n  origin: (origin, callback) => {\n    if (!origin || allowedOrigins.includes(origin) || origin.endsWith(\".vercel.app\")) {\n      callback(null, true);\n    } else {\n      callback(null, true);\n    }\n  },\n  credentials: true,\n}));\n\n// WEBHOOK RAW BODY\napp.use(\"/api/payments/webhook/stripe\", express.raw({ type: \"application/json\" }));\napp.use(\"/api/payments/webhook/paystack\", express.raw({ type: \"application/json\" }));\napp.use(\"/api/payments/webhook/flutterwave\", express.raw({ type: \"application/json\" }));\n\n// BODY PARSER\napp.use(express.json({ limit: \"2mb\" }));\napp.use(express.urlencoded({ extended: true, limit: \"2mb\" }));\napp.use(cookieParser());\napp.use(compression());\n\n// QUERY SANITIZATION\napp.use((req, _res, next) => {\n  for (const key in req.query) {\n    if (Array.isArray(req.query[key])) {\n      req.query[key] = (req.query[key] as string[]).at(-1) as any;\n    }\n  }\n  next();\n});\n\n// STATIC\napp.use(\"/uploads\", express.static(path.join(process.cwd(), \"uploads\")));\n\n// LOGGING\nif (process.env.NODE_ENV !== \"test\") {\n  app.use(morgan(\"combined\"));\n  app.use(requestLogger);\n}\n\n// RATE LIMIT\napp.use(\"/api\", globalRateLimiter);\n\n// HEALTH\napp.get(\"/api/health\", (_req: Request, res: Response) => {\n  res.json({ status: \"ok\", service: \"DropOS API\" });\n});\n\n// CORE BUSINESS ROUTES\napp.use(\"/api/auth\",                 authRoutes);\napp.use(\"/api/auth\",                 authRefreshRoutes);\napp.use(\"/api/stores\",               storeRoutes);\napp.use(\"/api/products\",             productRoutes);\napp.use(\"/api/orders\",               orderRoutes);\napp.use(\"/api/payments\",             paymentRoutes);\napp.use(\"/api/customers\",            customerRoutes);\napp.use(\"/api/admin\",                adminRoutes);\napp.use(\"/api/analytics\",            analyticsRoutes);\napp.use(\"/api/upload\",               uploadRoutes);\napp.use(\"/api/support\",              supportRoutes);\napp.use(\"/api/notifications\",        notificationRoutes);\napp.use(\"/api/coupons\",              couponRoutes);\napp.use(\"/api/discounts\",            discountRoutes);\napp.use(\"/api/affiliates\",           affiliateRoutes);\napp.use(\"/api/ai\",                   aiRoutes);\napp.use(\"/api/push\",                 pushRoutes);\napp.use(\"/api/shipping\",             shippingRoutes);\napp.use(\"/api/reviews\",              reviewRoutes);\napp.use(\"/api/invoices\",             invoiceRoutes);\napp.use(\"/api/email\",                emailRoutes);\napp.use(\"/api/abandoned-carts\",      abandonedCartRoutes);\napp.use(\"/api/notification-settings\",notifSettingsRoutes);\napp.use(\"/api/currency\",             currencyRoutes);\napp.use(\"/api/suppliers\",            supplierRoutes);\napp.use(\"/api/refunds\",              refundRoutes);\napp.use(\"/api/gift-cards\",           giftCardRoutes);\napp.use(\"/api/customer-auth\",        customerAccountRoutes);\napp.use(\"/api/funnel\",               funnelRoutes);\napp.use(\"/api/api-keys\",             apiKeyRoutes);\napp.use(\"/api/webhooks\",             webhookRoutes);\napp.use(\"/api/ops\",                  returnsRoutes);\napp.use(\"/api/2fa\",                  twoFARoutes);\napp.use(\"/api/product-subscriptions\",productSubscriptionRoutes);\napp.use(\"/api/upsell\",               upsellRoutes);\napp.use(\"/api/waitlist\",             waitlistRoutes);\n\n// KAI SYSTEM\napp.use(\"/api/kai\",              kaiRoutes);\napp.use(\"/api/kai/power\",        kaiPowerRoutes);\napp.use(\"/api/kai/agent\",        kaiAgentRoutes);\napp.use(\"/api/features\",         featuresRoutes);\napp.use(\"/api/loyalty\",          loyaltyRoutes);\napp.use(\"/api/super\",            superchargeRoutes);\napp.use(\"/api/theme\",            themeRoutes);\napp.use(\"/api/products/intel\",   productIntelRoutes);\napp.use(\"/api/intel\",            intelRoutes);\napp.use(\"/api/fulfillment\",      fulfillmentRoutes);\n\n// ERRORS\napp.use(\"/api/onboarding\",    onboardingRoutes);\napp.use(\"/api/milestones\",     milestoneRoutes);\napp.use(\"/api/contact\",        contactRoutes);\napp.use(\"/api/bundles\",        bundleRoutes);\napp.use(\"/api/group-buy\",      groupBuyRoutes);\napp.use(\"/api/referral\",       referralRoutes);\napp.use(\"/api/nav-level\",      navLevelRoutes);\napp.use(\"/api/reports\",        reportsRoutes);\napp.use(notFound);\napp.use(errorHandler);\n\nexport default app;","backend/src/routes/onboarding.routes.ts":"import { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { prisma } from \"../lib/prisma\";\n\nconst router = Router();\nrouter.use(authenticate);\n\n// POST /api/onboarding/complete\nrouter.post(\"/complete\", async (req: any, res: Response) => {\n  try {\n    const { niche, stage, goal, template } = req.body;\n    const userId  = req.user.id;\n    const storeId = req.user.stores?.[0]?.id;\n\n    // Update user as onboarded\n    const user = await prisma.user.update({\n      where: { id: userId },\n      data: { onboarded: true, onboardNiche: niche, onboardStage: stage, onboardGoal: goal, onboardTemplate: template },\n    });\n\n    // Apply template to store if exists\n    if (storeId && template) {\n      await prisma.store.update({\n        where: { id: storeId },\n        data: { templateId: template, primaryColor: getColorForNiche(niche) },\n      }).catch(() => {}); // Non-critical\n    }\n\n    // Generate KIRO welcome message based on answers\n    const nicheLabels: Record<string,string> = {\n      hair:\"Hair and Beauty\", fashion:\"Fashion and Clothing\", electronics:\"Electronics\",\n      food:\"Food and Drinks\", skincare:\"Skincare and Wellness\", home:\"Home and Living\",\n      kids:\"Kids and Baby\", other:\"your niche\",\n    };\n    const nicheLabel = nicheLabels[niche] || \"your niche\";\n\n    const kiroMessage = `Perfect. I am setting up your ${nicheLabel} store right now. I am picking the best template, importing trending products in your category, and configuring Paystack for Nigerian buyers. This takes about 10 seconds.`;\n\n    // Create first milestone: store setup\n    if (storeId) {\n      await prisma.milestone.create({\n        data: {\n          storeId, type: \"store_complete\",\n          title: \"Your store is live\",\n          message: `KIRO has set up your ${nicheLabel} store. Share your link and get your first sale today.`,\n          cta: { label: \"View your store\", href: \"/dashboard/stores\" },\n        },\n      }).catch(() => {});\n    }\n\n    res.json({ success: true, data: { kiroMessage, user: { ...user, password: undefined } } });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\nfunction getColorForNiche(niche: string): string {\n  const colors: Record<string,string> = {\n    hair:\"#E91E8C\", fashion:\"#8B5CF6\", electronics:\"#06B6D4\",\n    food:\"#F59E0B\", skincare:\"#10B981\", home:\"#F97316\", kids:\"#EC4899\",\n  };\n  return colors[niche] || \"#6B35E8\";\n}\n\nexport default router;\n","backend/src/routes/milestone.routes.ts":"import { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { prisma } from \"../lib/prisma\";\n\nconst router = Router();\nrouter.use(authenticate);\n\n// GET /api/milestones/:storeId\nrouter.get(\"/:storeId\", async (req: any, res: Response) => {\n  try {\n    const milestones = await prisma.milestone.findMany({\n      where: { storeId: req.params.storeId },\n      orderBy: { createdAt: \"desc\" },\n      take: 20,\n    });\n    res.json({ success: true, data: milestones });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\n// PATCH /api/milestones/:id/seen\nrouter.patch(\"/:id/seen\", async (req: any, res: Response) => {\n  try {\n    await prisma.milestone.update({ where: { id: req.params.id }, data: { seen: true } });\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\n// Internal: create milestone (called from other services)\nexport async function createMilestone(storeId: string, type: string, title: string, message: string, cta?: any) {\n  return prisma.milestone.create({ data: { storeId, type, title, message, cta } });\n}\n\nexport default router;\n","backend/src/routes/contact.routes.ts":"import { Router, Request, Response } from \"express\";\nimport { prisma } from \"../lib/prisma\";\n\nconst router = Router();\n\n// POST /api/contact\nrouter.post(\"/\", async (req: Request, res: Response) => {\n  try {\n    const { name, email, subject, message } = req.body;\n    if (!name || !email || !message) {\n      return res.status(400).json({ success: false, message: \"Name, email and message are required\" });\n    }\n    await prisma.contactMessage.create({ data: { name, email, subject: subject || \"general\", message } });\n    // TODO: send email notification to hello@droposhq.com via Resend\n    res.json({ success: true, message: \"Message received. We will reply within 24 hours.\" });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\nexport default router;\n","backend/src/routes/bundle.routes.ts":"import { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { prisma } from \"../lib/prisma\";\n\nconst router = Router();\nrouter.use(authenticate);\n\n// GET /api/bundles/:storeId\nrouter.get(\"/:storeId\", async (req: any, res: Response) => {\n  try {\n    const bundles = await prisma.bundle.findMany({\n      where: { storeId: req.params.storeId },\n      orderBy: { createdAt: \"desc\" },\n    });\n    res.json({ success: true, data: bundles });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\n// POST /api/bundles/:storeId\nrouter.post(\"/:storeId\", async (req: any, res: Response) => {\n  try {\n    const { name, productIds, discountPercent } = req.body;\n    if (!name || !productIds?.length) return res.status(400).json({ success: false, message: \"Name and products required\" });\n\n    // Get products to calculate price\n    const products = await prisma.product.findMany({ where: { id: { in: productIds } } });\n    const originalPrice = products.reduce((a: number, p: any) => a + (p.price || 0), 0);\n    const bundlePrice   = originalPrice * (1 - (discountPercent || 10) / 100);\n\n    const bundle = await prisma.bundle.create({\n      data: { storeId: req.params.storeId, name, productIds, discountPercent: discountPercent || 10, originalPrice, bundlePrice },\n    });\n    res.status(201).json({ success: true, data: bundle });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\n// DELETE /api/bundles/:storeId/:bundleId\nrouter.delete(\"/:storeId/:bundleId\", async (req: any, res: Response) => {\n  try {\n    await prisma.bundle.delete({ where: { id: req.params.bundleId } });\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\nexport default router;\n","backend/src/routes/groupbuy.routes.ts":"import { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { prisma } from \"../lib/prisma\";\n\nconst router = Router();\n\n// Public: GET /api/group-buy/public/:id\nrouter.get(\"/public/:id\", async (req: Request, res: Response) => {\n  try {\n    const gb = await prisma.groupBuy.findUnique({\n      where: { id: req.params.id },\n      include: {\n        store:   { select: { name: true, slug: true, logo: true, primaryColor: true, currency: true } },\n        product: { select: { name: true, images: true, price: true } },\n        members: { select: { name: true, createdAt: true }, orderBy: { createdAt: \"asc\" } },\n      },\n    });\n    if (!gb) return res.status(404).json({ success: false, message: \"Group buy not found\" });\n    res.json({ success: true, data: { ...gb, memberCount: gb.members.length } });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\n// Public: POST /api/group-buy/:id/join\nrouter.post(\"/:id/join\", async (req: Request, res: Response) => {\n  try {\n    const { name, email } = req.body;\n    if (!name || !email) return res.status(400).json({ success: false, message: \"Name and email required\" });\n\n    const gb = await prisma.groupBuy.findUnique({ where: { id: req.params.id } });\n    if (!gb || !gb.active) return res.status(404).json({ success: false, message: \"Group buy not found or ended\" });\n    if (new Date(gb.endsAt) < new Date()) return res.status(400).json({ success: false, message: \"Group buy has ended\" });\n\n    // Check if already joined\n    const existing = await prisma.groupBuyMember.findFirst({ where: { groupBuyId: req.params.id, email } });\n    if (existing) return res.status(400).json({ success: false, message: \"You have already joined this group buy\" });\n\n    await prisma.groupBuyMember.create({ data: { groupBuyId: req.params.id, name, email } });\n    res.json({ success: true, message: \"Joined! We will email you when the group fills up.\" });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\n// Authenticated: POST /api/group-buy (create)\nrouter.post(\"/\", authenticate as any, async (req: any, res: Response) => {\n  try {\n    const { storeId, productId, title, description, groupPrice, originalPrice, minMembers, endsAt } = req.body;\n    const gb = await prisma.groupBuy.create({\n      data: { storeId, productId, title, description, groupPrice, originalPrice, minMembers: minMembers || 10, endsAt: new Date(endsAt) },\n    });\n    res.status(201).json({ success: true, data: gb });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\n// GET /api/group-buy/store/:storeId (list)\nrouter.get(\"/store/:storeId\", authenticate as any, async (req: any, res: Response) => {\n  try {\n    const gbs = await prisma.groupBuy.findMany({\n      where: { storeId: req.params.storeId },\n      include: { _count: { select: { members: true } } },\n      orderBy: { createdAt: \"desc\" },\n    });\n    res.json({ success: true, data: gbs });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\nexport default router;\n","backend/src/routes/referral.routes.ts":"import { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { prisma } from \"../lib/prisma\";\nimport crypto from \"crypto\";\n\nconst router = Router();\nrouter.use(authenticate);\n\n// GET /api/referral/stats\nrouter.get(\"/stats\", async (req: any, res: Response) => {\n  try {\n    let referral = await prisma.referral.findUnique({ where: { userId: req.user.id } });\n    if (!referral) {\n      const code = crypto.randomBytes(4).toString(\"hex\").toUpperCase();\n      referral = await prisma.referral.create({ data: { userId: req.user.id, code } });\n    }\n    res.json({ success: true, data: referral });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\n// POST /api/referral/click (track referral click)\nrouter.post(\"/click\", async (req: Request, res: Response) => {\n  try {\n    const { code } = req.body;\n    if (!code) return res.status(400).json({ success: false });\n    await prisma.referral.update({ where: { code }, data: { clicks: { increment: 1 } } }).catch(() => {});\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\nexport default router;\n","backend/src/routes/navlevel.routes.ts":"import { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { prisma } from \"../lib/prisma\";\n\nconst router = Router();\nrouter.use(authenticate);\n\n// GET /api/nav-level/:storeId\nrouter.get(\"/:storeId\", async (req: any, res: Response) => {\n  try {\n    const storeId = req.params.storeId;\n    const [productCount, orderCount, store] = await Promise.all([\n      prisma.product.count({ where: { storeId } }),\n      prisma.order.count({ where: { storeId } }),\n      prisma.store.findUnique({ where: { id: storeId }, select: { paystackConnected: true } }),\n    ]);\n    res.json({\n      success: true,\n      data: { productCount, orderCount, hasPaystack: store?.paystackConnected ?? false },\n    });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\nexport default router;\n","backend/src/routes/reports.routes.ts":"import { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { prisma } from \"../lib/prisma\";\n\nconst router = Router();\nrouter.use(authenticate);\n\nfunction toCSV(headers: string[], rows: any[][]): string {\n  const escape = (v: any) => `\"${String(v ?? \"\").replace(/\"/g, '\"\"')}\"`;\n  return [headers.map(escape).join(\",\"), ...rows.map(r => r.map(escape).join(\",\"))].join(\"\\n\");\n}\n\n// GET /api/reports/:storeId/:reportId\nrouter.get(\"/:storeId/:reportId\", async (req: any, res: Response) => {\n  try {\n    const { storeId, reportId } = req.params;\n    const period = parseInt(req.query.period as string) || 30;\n    const format = req.query.format as string || \"csv\";\n    const since  = new Date(Date.now() - period * 86400000);\n\n    let csv = \"\";\n    let filename = `dropos-${reportId}`;\n\n    switch (reportId) {\n      case \"revenue\": {\n        const orders = await prisma.order.findMany({\n          where: { storeId, createdAt: { gte: since } },\n          select: { id: true, orderNumber: true, total: true, status: true, createdAt: true },\n          orderBy: { createdAt: \"desc\" },\n        });\n        csv = toCSV(\n          [\"Order ID\", \"Order Number\", \"Total (NGN)\", \"Status\", \"Date\"],\n          orders.map(o => [o.id, o.orderNumber, o.total, o.status, o.createdAt.toISOString().split(\"T\")[0]])\n        );\n        filename = `dropos-revenue-${period}days`;\n        break;\n      }\n      case \"orders\": {\n        const orders = await prisma.order.findMany({\n          where: { storeId, createdAt: { gte: since } },\n          include: { customer: { select: { name: true, email: true } }, items: { include: { product: { select: { name: true } } } } },\n          orderBy: { createdAt: \"desc\" },\n        });\n        csv = toCSV(\n          [\"Order ID\", \"Customer Name\", \"Customer Email\", \"Items\", \"Total\", \"Status\", \"Date\"],\n          orders.map(o => [\n            o.id, o.customer?.name ?? \"Guest\", o.customer?.email ?? \"\",\n            o.items.map((i: any) => i.product?.name ?? \"\").join(\"; \"),\n            o.total, o.status, o.createdAt.toISOString().split(\"T\")[0],\n          ])\n        );\n        filename = `dropos-orders-${period}days`;\n        break;\n      }\n      case \"customers\": {\n        const customers = await prisma.storeCustomer.findMany({\n          where: { storeId },\n          include: { _count: { select: { orders: true } } },\n          orderBy: { createdAt: \"desc\" },\n        });\n        csv = toCSV(\n          [\"Customer ID\", \"Name\", \"Email\", \"Phone\", \"Total Orders\", \"Joined\"],\n          customers.map(c => [c.id, c.name, c.email, c.phone ?? \"\", c._count.orders, c.createdAt.toISOString().split(\"T\")[0]])\n        );\n        filename = `dropos-customers`;\n        break;\n      }\n      case \"products\": {\n        const products = await prisma.product.findMany({\n          where: { storeId },\n          select: { id: true, name: true, price: true, inventory: true, status: true, createdAt: true },\n          orderBy: { createdAt: \"desc\" },\n        });\n        csv = toCSV(\n          [\"Product ID\", \"Name\", \"Price (NGN)\", \"Stock\", \"Status\", \"Created\"],\n          products.map(p => [p.id, p.name, p.price, p.inventory, p.status, p.createdAt.toISOString().split(\"T\")[0]])\n        );\n        filename = `dropos-products`;\n        break;\n      }\n      case \"inventory\": {\n        const products = await prisma.product.findMany({\n          where: { storeId },\n          select: { id: true, name: true, sku: true, inventory: true, price: true },\n        });\n        csv = toCSV(\n          [\"Product ID\", \"Name\", \"SKU\", \"Stock\", \"Price (NGN)\"],\n          products.map(p => [p.id, p.name, p.sku ?? \"\", p.inventory, p.price])\n        );\n        filename = `dropos-inventory`;\n        break;\n      }\n      case \"tax\": {\n        const orders = await prisma.order.findMany({\n          where: { storeId, createdAt: { gte: since } },\n          select: { id: true, orderNumber: true, total: true, tax: true, createdAt: true },\n          orderBy: { createdAt: \"desc\" },\n        });\n        csv = toCSV(\n          [\"Order ID\", \"Order Number\", \"Subtotal\", \"Tax\", \"Date\"],\n          orders.map(o => [o.id, o.orderNumber, (o.total - (o.tax || 0)).toFixed(2), (o.tax || 0).toFixed(2), o.createdAt.toISOString().split(\"T\")[0]])\n        );\n        filename = `dropos-tax-${period}days`;\n        break;\n      }\n      default:\n        return res.status(400).json({ success: false, message: \"Unknown report type\" });\n    }\n\n    res.setHeader(\"Content-Type\", \"text/csv\");\n    res.setHeader(\"Content-Disposition\", `attachment; filename=\"${filename}.csv\"`);\n    res.send(csv);\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\nexport default router;\n","backend/prisma/schema.prisma":"// prisma/schema.prisma\n// DropOS - Full Multi-Tenant SaaS Schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─── Enums ───────────────────────────────────────────────────────────────────\n\nenum Role {\n  SUPER_ADMIN\n  STORE_OWNER\n  CUSTOMER\n}\n\nenum UserStatus {\n  ACTIVE\n  SUSPENDED\n  PENDING_VERIFICATION\n  BANNED\n}\n\nenum PlanType {\n  STARTER\n  PRO\n  ADVANCED\n}\n\nenum StoreStatus {\n  ACTIVE\n  SUSPENDED\n  PENDING\n  ARCHIVED\n}\n\nenum ProductStatus {\n  ACTIVE\n  DRAFT\n  OUT_OF_STOCK\n  ARCHIVED\n}\n\nenum OrderStatus {\n  PENDING\n  PROCESSING\n  SHIPPED\n  DELIVERED\n  COMPLETED\n  CANCELLED\n  REFUNDED\n}\n\nenum PaymentStatus {\n  PENDING\n  SUCCESS\n  FAILED\n  REFUNDED\n  DISPUTED\n}\n\nenum PaymentGateway {\n  STRIPE\n  PAYSTACK\n  FLUTTERWAVE\n}\n\nenum SubscriptionStatus {\n  ACTIVE\n  CANCELLED\n  EXPIRED\n  PAST_DUE\n}\n\nenum SupportStatus {\n  OPEN\n  IN_PROGRESS\n  RESOLVED\n  CLOSED\n}\n\nenum Priority {\n  LOW\n  MEDIUM\n  HIGH\n  URGENT\n}\n\nenum LogLevel {\n  INFO\n  WARN\n  ERROR\n  CRITICAL\n}\n\n// ─── User ────────────────────────────────────────────────────────────────────\n\nmodel User {\n  id                String     @id @default(uuid())\n  email             String     @unique\n  password          String\n  name              String\n  phone             String?\n  avatar            String?\n  role              Role       @default(STORE_OWNER)\n  status            UserStatus @default(PENDING_VERIFICATION)\n  emailVerified     Boolean    @default(false)\n  emailVerifyToken  String?\n  passwordResetToken String?\n  passwordResetExpiry DateTime?\n  twoFAEnabled      Boolean    @default(false)\n  twoFASecret       String?\n  lastLogin         DateTime?\n  loginAttempts     Int        @default(0)\n  lockedUntil       DateTime?\n  refreshToken      String?\n  adminNotes        String?\n  flags             String[]   @default([])\n  onboarded         Boolean    @default(false)\n  onboardNiche      String?\n  onboardStage      String?\n  onboardGoal       String?\n  onboardTemplate   String?\n  country           String?\n  city              String?\n  timezone          String?    @default(\"UTC\")\n  createdAt         DateTime   @default(now())\n  updatedAt         DateTime   @updatedAt\n\n  // Relations\n  stores            Store[]\n  kaiConversations  KaiConversation[]\n  subscription      Subscription?\n  supportTickets    SupportTicket[]\n  notifications     Notification[]\n  auditLogs         AuditLog[]\n  pushSubscriptions PushSubscription[]\n  referral          Referral?\n\n  @@index([email])\n  @@index([role])\n  @@index([status])\n  @@map(\"users\")\n}\n\n// ─── Store ───────────────────────────────────────────────────────────────────\n\nmodel Store {\n  id              String      @id @default(uuid())\n  ownerId         String\n  name            String\n  slug            String      @unique\n  description     String?\n  logo            String?\n  banner          String?\n  domain          String?     @unique\n  customDomain    String?     @unique\n  templateId      String?\n  paystackConnected Boolean  @default(false)\n  status          StoreStatus @default(PENDING)\n  primaryColor    String?     @default(\"#7c3aed\")\n  accentColor     String?     @default(\"#a855f7\")\n  theme           String?     @default(\"default\")\n  secondaryColor  String?\n  fontFamily      String?     @default(\"DM Sans\")\n  borderRadius    String?     @default(\"rounded\")\n  tagline         String?\n  showReviews     Boolean     @default(true)\n  showInventory   Boolean     @default(true)\n  productsPerRow  Int         @default(4)\n  currency        String      @default(\"USD\")\n  country         String?\n  address         String?\n  supportEmail    String?\n  supportPhone    String?\n  taxRate         Float?      @default(0)\n  shippingEnabled Boolean     @default(true)\n  freeShippingMin Float?\n  metaTitle         String?\n  metaDescription   String?\n  // ── SMS / WhatsApp via Twilio ─────────────────────────────────────────────\n  suppliers           Supplier[]\n  fulfillmentOrders   FulfillmentOrder[]\n\n  // ── Multi-currency ───────────────────────────────────────────────────────────\n  supportedCurrencies Json?       // e.g. [\"USD\",\"EUR\",\"GBP\",\"NGN\"]\n  autoDetectCurrency  Boolean     @default(true)\n  smsEnabled        Boolean     @default(false)\n  smsPhone          String?     // owner's phone for incoming alerts  e.g. +2348012345678\n  whatsappEnabled   Boolean     @default(false)\n  whatsappPhone     String?     // owner's WhatsApp number\n  // ── Live Chat widget ────────────────────────────────────────────────────────\n  liveChatProvider  String?     // \"tawk\", \"crisp\", \"tidio\", \"whatsapp\", or null\n  liveChatId        String?     // Tawk.to property ID / Crisp website ID / Tidio key\n  liveChatEnabled   Boolean     @default(false)\n  notifyOwnerSms    Boolean     @default(true)   // SMS owner on new order\n  notifyCustomerSms Boolean     @default(false)  // SMS customer on order + status\n  createdAt         DateTime    @default(now())\n  updatedAt       DateTime    @updatedAt\n\n  // Relations\n  owner           User        @relation(fields: [ownerId], references: [id], onDelete: Cascade)\n  products        Product[]\n  orders          Order[]\n  customers       StoreCustomer[]\n  payments        Payment[]\n  analytics       Analytics[]\n  shippingZones   ShippingZone[]\n  coupons         Coupon[]\n  reviews         Review[]\n  abandonedCarts  AbandonedCart[]\n\n  discounts       Discount[]\n  refunds         Refund[]\n  giftCards       GiftCard[]\n  webhooks        StoreWebhook[]\n  flashSales      FlashSale[]\n  backups         StoreBackup[]\n  apiKeys         ApiKey[]\n  returnRequests  ReturnRequest[]\n  affiliates      Affiliate[]\n  @@index([ownerId])\n  @@index([slug])\n  @@index([status])\n  @@map(\"stores\")\n  integrations    StoreIntegration[]\n}\n\n// ─── Product ─────────────────────────────────────────────────────────────────\n\nmodel Product {\n  id              String        @id @default(uuid())\n  storeId         String\n  name            String\n  slug            String\n  description     String?\n  price           Float\n  comparePrice    Float?\n  costPrice       Float?\n  sku             String?\n  barcode         String?\n  weight          Float?\n  inventory       Int           @default(0)\n  trackInventory  Boolean       @default(true)\n  allowBackorder  Boolean       @default(false)\n  images          String[]      @default([])\n  category        String?\n  tags            String[]      @default([])\n  status          ProductStatus @default(DRAFT)\n  isDigital       Boolean       @default(false)\n  metaTitle       String?\n  metaDescription String?\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n\n  // Relations\n  store           Store         @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  variants        ProductVariant[]\n  orderItems      OrderItem[]\n  reviews         Review[]\n  supplierProducts SupplierProduct[]\n\n  @@unique([storeId, slug])\n  @@index([storeId])\n  @@index([status])\n  @@map(\"products\")\n}\n\nmodel ProductVariant {\n  id          String   @id @default(uuid())\n  productId   String\n  name        String\n  value       String\n  price       Float?\n  inventory   Int      @default(0)\n  sku         String?\n  image       String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  product     Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@index([productId])\n  @@map(\"product_variants\")\n}\n\n// ─── Store Customer ──────────────────────────────────────────────────────────\n\nmodel StoreCustomer {\n  id              String    @id @default(uuid())\n  storeId         String\n  email           String\n  name            String\n  phone           String?\n  address         Json?\n  emailVerified   Boolean   @default(false)\n  totalSpent      Float     @default(0)\n  orderCount      Int       @default(0)\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  store           Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  orders          Order[]\n\n  @@unique([storeId, email])\n  @@index([storeId])\n  @@map(\"store_customers\")\n}\n\n// ─── Order ───────────────────────────────────────────────────────────────────\n\nmodel Order {\n  id                String      @id @default(uuid())\n  orderNumber       String      @unique\n  storeId           String\n  customerId        String?\n  customerEmail     String\n  customerName      String\n  customerPhone     String?\n  shippingAddress   Json?\n  billingAddress    Json?\n  status            OrderStatus @default(PENDING)\n  subtotal          Float\n  shippingCost      Float       @default(0)\n  taxAmount         Float       @default(0)\n  discountAmount    Float       @default(0)\n  total             Float\n  currency          String      @default(\"USD\")\n  notes             String?\n  trackingNumber    String?\n  trackingUrl       String?\n  refundAmount      Float?\n  cancelReason      String?\n  createdAt         DateTime    @default(now())\n  updatedAt         DateTime    @updatedAt\n\n  store             Store         @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  customer          StoreCustomer? @relation(fields: [customerId], references: [id])\n  items             OrderItem[]\n  payment           Payment?\n  refunds           Refund[]\n  returns           ReturnRequest[]\n\n  @@index([storeId])\n  @@index([status])\n  @@index([orderNumber])\n  @@map(\"orders\")\n}\n\nmodel OrderItem {\n  id          String   @id @default(uuid())\n  orderId     String\n  productId   String\n  variantId   String?\n  name        String\n  sku         String?\n  price       Float\n  quantity    Int\n  total       Float\n  image       String?\n  createdAt   DateTime @default(now())\n\n  order       Order    @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  product     Product  @relation(fields: [productId], references: [id])\n\n  @@index([orderId])\n  @@map(\"order_items\")\n}\n\n// ─── Payment ─────────────────────────────────────────────────────────────────\n\nmodel Payment {\n  id                String         @id @default(uuid())\n  orderId           String         @unique\n  storeId           String\n  gateway           PaymentGateway\n  gatewayReference  String?\n  gatewayResponse   Json?\n  amount            Float\n  currency          String         @default(\"USD\")\n  platformFee       Float\n  platformFeePercent Float\n  storeEarnings     Float\n  status            PaymentStatus  @default(PENDING)\n  paidAt            DateTime?\n  refundedAt        DateTime?\n  metadata          Json?\n  createdAt         DateTime       @default(now())\n  updatedAt         DateTime       @updatedAt\n\n  order             Order          @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  store             Store          @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([status])\n  @@index([gateway])\n  @@map(\"payments\")\n}\n\n// ─── Subscription ────────────────────────────────────────────────────────────\n\nmodel Subscription {\n  id                  String             @id @default(uuid())\n  userId              String             @unique\n  plan                PlanType           @default(STARTER)\n  status              SubscriptionStatus @default(ACTIVE)\n  currentPeriodStart  DateTime\n  currentPeriodEnd    DateTime\n  cancelAtPeriodEnd   Boolean            @default(false)\n  stripeSubId         String?\n  paystackSubCode     String?\n  price               Float\n  currency            String             @default(\"USD\")\n  createdAt           DateTime           @default(now())\n  updatedAt           DateTime           @updatedAt\n\n  user                User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([status])\n  @@map(\"subscriptions\")\n}\n\n// ─── Analytics ───────────────────────────────────────────────────────────────\n\nmodel Analytics {\n  id            String   @id @default(uuid())\n  storeId       String\n  date          DateTime @db.Date\n  views         Int      @default(0)\n  visitors      Int      @default(0)\n  orders        Int      @default(0)\n  revenue       Float    @default(0)\n  conversions   Float    @default(0)\n  avgOrderValue Float    @default(0)\n  newCustomers  Int      @default(0)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  store         Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@unique([storeId, date])\n  @@index([storeId])\n  @@map(\"analytics\")\n}\n\n// ─── Shipping Zone ───────────────────────────────────────────────────────────\n\n\n// ─── Support Ticket ──────────────────────────────────────────────────────────\n\nmodel SupportTicket {\n  id          String        @id @default(uuid())\n  userId      String\n  subject     String\n  message     String\n  status      SupportStatus @default(OPEN)\n  priority    Priority      @default(MEDIUM)\n  adminReply  String?\n  resolvedAt  DateTime?\n  createdAt   DateTime      @default(now())\n  updatedAt   DateTime      @updatedAt\n\n  user        User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  replies     TicketReply[]\n\n  @@index([userId])\n  @@index([status])\n  @@map(\"support_tickets\")\n}\n\nmodel TicketReply {\n  id        String        @id @default(uuid())\n  ticketId  String\n  senderId  String\n  isAdmin   Boolean       @default(false)\n  message   String\n  createdAt DateTime      @default(now())\n\n  ticket    SupportTicket @relation(fields: [ticketId], references: [id], onDelete: Cascade)\n\n  @@index([ticketId])\n  @@map(\"ticket_replies\")\n}\n\n// ─── Platform Settings ───────────────────────────────────────────────────────\n\nmodel PlatformSettings {\n  id                  String   @id @default(\"singleton\")\n  platformFeePercent  Float    @default(10)\n  starterPrice        Float    @default(9)\n  proPrice            Float    @default(29)\n  advancedPrice       Float    @default(79)\n  maintenanceMode     Boolean  @default(false)\n  allowRegistration   Boolean  @default(true)\n  maxStoresPerOwner   Json     @default(\"{\\\"STARTER\\\":1,\\\"PRO\\\":3,\\\"ADVANCED\\\":999}\")\n  maxProductsPerStore Json     @default(\"{\\\"STARTER\\\":50,\\\"PRO\\\":500,\\\"ADVANCED\\\":999999}\")\n  smtpConfig          Json?\n  updatedAt           DateTime @updatedAt\n\n  @@map(\"platform_settings\")\n}\n\n// ─── Notification ────────────────────────────────────────────────────────────\n\nmodel Notification {\n  id        String   @id @default(uuid())\n  userId    String\n  title     String\n  message   String\n  type      String   @default(\"info\")\n  read      Boolean  @default(false)\n  link      String?\n  createdAt DateTime @default(now())\n\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([read])\n  @@map(\"notifications\")\n}\n\n// ─── Audit Log ───────────────────────────────────────────────────────────────\n\nmodel AuditLog {\n  id          String   @id @default(uuid())\n  userId      String?\n  action      String\n  entity      String\n  entityId    String?\n  oldValues   Json?\n  newValues   Json?\n  ipAddress   String?\n  userAgent   String?\n  level       LogLevel @default(INFO)\n  createdAt   DateTime @default(now())\n\n  user        User?    @relation(fields: [userId], references: [id])\n\n  @@index([userId])\n  @@index([entity])\n  @@index([createdAt])\n  @@map(\"audit_logs\")\n}\n\n// ─── Error Log ───────────────────────────────────────────────────────────────\n\nmodel ErrorLog {\n  id          String   @id @default(uuid())\n  message     String\n  stack       String?\n  path        String?\n  method      String?\n  statusCode  Int?\n  userId      String?\n  ipAddress   String?\n  resolved    Boolean  @default(false)\n  createdAt   DateTime @default(now())\n\n  @@index([resolved])\n  @@index([createdAt])\n  @@map(\"error_logs\")\n}\n\n// ─── Coupon ──────────────────────────────────────────────────────────────────\n\nmodel Coupon {\n  id            String    @id @default(uuid())\n  storeId       String\n  code          String\n  type          String    // PERCENTAGE | FIXED\n  value         Float\n  minOrderValue Float     @default(0)\n  maxUses       Int?\n  usedCount     Int       @default(0)\n  isActive      Boolean   @default(true)\n  expiresAt     DateTime?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  store         Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@unique([storeId, code])\n  @@index([storeId])\n  @@map(\"coupons\")\n}\n\n// ─── Shipping Zone ───────────────────────────────────────────────────────────\n\nmodel ShippingZone {\n  id            String   @id @default(uuid())\n  storeId       String\n  name          String\n  countries     String[]\n  shippingRate  Float    @default(0)\n  freeThreshold Float?\n  estimatedDays String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  store         Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@map(\"shipping_zones\")\n}\n\n// ─── Review ──────────────────────────────────────────────────────────────────\n\nmodel Review {\n  id         String   @id @default(uuid())\n  storeId    String\n  productId  String\n  name       String\n  email      String\n  rating     Int      // 1-5\n  title      String?\n  body       String\n  photos     String[] // array of image URLs\n  approved   Boolean  @default(false)\n  featured   Boolean  @default(false)\n  helpful    Int      @default(0)\n  verified   Boolean  @default(false)\n  orderId    String?  // set if from verified purchase\n  replyBody  String?  // store owner reply\n  repliedAt  DateTime?\n  source     String?  // \"email\" | \"in-app\" | \"import\"\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  store   Store   @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@index([productId])\n  @@index([storeId])\n  @@map(\"reviews\")\n}\n\n// ─── Abandoned Cart ───────────────────────────────────────────────────────────\n\nmodel AbandonedCart {\n  id            String   @id @default(uuid())\n  storeId       String\n  email         String\n  name          String?\n  items         Json     // CartItem[]\n  total         Float\n  currency      String   @default(\"USD\")\n  token         String   @unique @default(uuid())  // recovery link token\n  recovered     Boolean  @default(false)\n  emailSent     Boolean  @default(false)\n  emailSentAt   DateTime?\n  recoveredAt   DateTime?\n  reminderCount Int      @default(0)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  store         Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([email])\n  @@index([token])\n  @@index([recovered, emailSent])\n  @@map(\"abandoned_carts\")\n}\n\n// ─── Supplier ─────────────────────────────────────────────────────────────────\n\nmodel Supplier {\n  id           String       @id @default(uuid())\n  storeId      String\n  name         String\n  type         SupplierType @default(MANUAL)\n  websiteUrl   String?\n  apiKey       String?\n  apiSecret    String?\n  contactEmail String?\n  contactName  String?\n  notes        String?\n  isActive     Boolean      @default(true)\n  autoFulfill  Boolean      @default(false)  // auto-forward orders when PROCESSING\n  fulfillEmail String?                        // email to send order details to\n  webhookUrl   String?                        // POST order JSON here on new order\n  createdAt    DateTime     @default(now())\n  updatedAt    DateTime     @updatedAt\n\n  store            Store             @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  products         SupplierProduct[]\n  fulfillmentOrders FulfillmentOrder[]\n\n  @@index([storeId])\n  @@map(\"suppliers\")\n}\n\nmodel SupplierProduct {\n  id              String   @id @default(uuid())\n  supplierId      String\n  productId       String\n  supplierSku     String?             // SKU in supplier's system\n  supplierUrl     String?             // original product URL (e.g. AliExpress)\n  supplierPrice   Float?              // cost from supplier (in supplier's currency)\n  supplierCurrency String  @default(\"USD\")\n  processingDays  Int?                // how many days to process\n  shippingDays    Int?                // estimated shipping\n  lastSynced      DateTime?\n  stockStatus     String?             // \"IN_STOCK\" | \"LOW_STOCK\" | \"OUT_OF_STOCK\"\n  priority        Int      @default(1)  // 1 = primary, higher = fallback\n  isActive        Boolean  @default(true)\n  notes           String?             // internal notes\n  createdAt       DateTime @default(now())\n\n  supplier  Supplier @relation(fields: [supplierId], references: [id], onDelete: Cascade)\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@unique([supplierId, productId])\n  @@index([productId])\n  @@map(\"supplier_products\")\n}\n\nmodel FulfillmentOrder {\n  id          String            @id @default(uuid())\n  orderId     String\n  supplierId  String\n  storeId     String\n  status      FulfillmentStatus @default(PENDING)\n  sentAt      DateTime?\n  confirmedAt DateTime?\n  notes       String?\n  supplierRef String?           // reference/tracking from supplier\n  method      String?           // \"EMAIL\" | \"WEBHOOK\" | \"MANUAL\"\n  payload     Json?             // what was sent to supplier\n  createdAt   DateTime          @default(now())\n  updatedAt   DateTime          @updatedAt\n\n  supplier Supplier @relation(fields: [supplierId], references: [id])\n  store    Store    @relation(fields: [storeId],    references: [id], onDelete: Cascade)\n\n  @@index([orderId])\n  @@index([supplierId])\n  @@index([storeId])\n  @@map(\"fulfillment_orders\")\n}\n\n\nenum SupplierType {\n  MANUAL\n  ALIEXPRESS\n  CSV\n  WEBHOOK\n}\n\nenum FulfillmentStatus {\n  PENDING\n  SENT\n  CONFIRMED\n  SHIPPED\n  FAILED\n}\n\n\n// ─── Discount Engine ─────────────────────────────────────────────────────────\n\nmodel Discount {\n  id          String       @id @default(uuid())\n  storeId     String\n  name        String\n  description String?\n  type        DiscountType\n  status      DiscountStatus @default(ACTIVE)\n  priority    Int          @default(0)   // higher = applied first\n  stackable   Boolean      @default(false)\n\n  // Trigger conditions\n  minOrderValue    Float?\n  minQuantity      Int?\n  customerTag      String?  // e.g. \"VIP\", \"wholesale\"\n  productIds       String[] // empty = all products\n  collectionIds    String[]\n  firstOrderOnly   Boolean  @default(false)\n\n  // Value / Action\n  valueType   DiscountValueType\n  value       Float             // %, fixed $, or new price\n  maxDiscount Float?            // cap on percentage discounts\n  freeShipping Boolean          @default(false)\n\n  // BOGO fields\n  bogoRequiredQty  Int?         // buy X\n  bogoGetQty       Int?         // get Y\n  bogoPctOff       Float?       // discount on the free item (100 = fully free)\n\n  // Tiered pricing (JSON array of {qty, pct})\n  tiers       Json?            // [{minQty:2,discount:10},{minQty:5,discount:20}]\n\n  // Flash sale\n  flashSaleEndsAt DateTime?\n  flashSaleStartsAt DateTime?\n\n  // Usage limits\n  maxUses       Int?\n  maxUsesPerCustomer Int?\n  usedCount     Int       @default(0)\n\n  // Validity\n  startsAt   DateTime?\n  expiresAt  DateTime?\n  isAutomatic Boolean   @default(false) // no code needed\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  store  Store            @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  usages DiscountUsage[]\n\n  @@index([storeId])\n  @@map(\"discounts\")\n}\n\nmodel DiscountUsage {\n  id          String   @id @default(uuid())\n  discountId  String\n  orderId     String\n  customerId  String?\n  amountSaved Float\n  appliedAt   DateTime @default(now())\n\n  discount Discount @relation(fields: [discountId], references: [id], onDelete: Cascade)\n\n  @@index([discountId])\n  @@index([orderId])\n  @@map(\"discount_usages\")\n}\n\nenum DiscountType {\n  AUTOMATIC     // applies automatically at checkout\n  BOGO          // buy X get Y\n  TIERED        // volume tiers\n  FLASH_SALE    // time-limited\n  PERCENTAGE    // classic % off\n  FIXED         // fixed $ off\n  FREE_SHIPPING // free shipping\n  BUNDLE        // spend X get Y\n}\n\nenum DiscountStatus {\n  ACTIVE\n  PAUSED\n  EXPIRED\n  SCHEDULED\n}\n\nenum DiscountValueType {\n  PERCENTAGE\n  FIXED_AMOUNT\n  NEW_PRICE\n  FREE\n}\n\n// ─── Referral & Affiliate System ─────────────────────────────────────────────\n\nmodel Affiliate {\n  id          String          @id @default(uuid())\n  storeId     String\n  name        String\n  email       String\n  code        String          // unique referral code\n  status      AffiliateStatus @default(PENDING)\n  commissionPct Float         @default(10)  // % of order value\n  commissionFlat Float?       // flat $ per sale (override)\n  payoutMethod  String?       // \"paypal\" | \"bank\" | \"store_credit\"\n  payoutDetails Json?         // encrypted payout info\n  totalEarned   Float         @default(0)\n  totalPaid     Float         @default(0)\n  totalClicks   Int           @default(0)\n  totalOrders   Int           @default(0)\n  notes         String?\n  createdAt   DateTime        @default(now())\n  updatedAt   DateTime        @updatedAt\n\n  store     Store             @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  referrals ReferralConversion[]\n  payouts   AffiliatePayout[]\n\n  @@unique([storeId, code])\n  @@index([storeId])\n  @@map(\"affiliates\")\n}\n\nmodel ReferralConversion {\n  id          String   @id @default(uuid())\n  affiliateId String\n  orderId     String\n  storeId     String\n  orderValue  Float\n  commission  Float\n  status      String   @default(\"PENDING\")  // PENDING | APPROVED | PAID | REJECTED\n  createdAt   DateTime @default(now())\n\n  affiliate Affiliate @relation(fields: [affiliateId], references: [id], onDelete: Cascade)\n\n  @@index([affiliateId])\n  @@index([orderId])\n  @@map(\"referral_conversions\")\n}\n\nmodel AffiliatePayout {\n  id          String   @id @default(uuid())\n  affiliateId String\n  storeId     String\n  amount      Float\n  method      String\n  status      String   @default(\"PENDING\")  // PENDING | SENT | FAILED\n  reference   String?\n  note        String?\n  createdAt   DateTime @default(now())\n\n  affiliate Affiliate @relation(fields: [affiliateId], references: [id], onDelete: Cascade)\n\n  @@index([affiliateId])\n  @@map(\"affiliate_payouts\")\n}\n\n// Affiliate click tracking\nmodel ReferralClick {\n  id          String   @id @default(uuid())\n  affiliateId String\n  storeId     String\n  ip          String?\n  userAgent   String?\n  page        String?\n  converted   Boolean  @default(false)\n  createdAt   DateTime @default(now())\n\n  @@index([affiliateId])\n  @@map(\"referral_clicks\")\n}\n\nenum AffiliateStatus {\n  PENDING\n  ACTIVE\n  PAUSED\n  SUSPENDED\n}\n\n// ─── Web Push Subscriptions ──────────────────────────────────────────────────\n\nmodel PushSubscription {\n  id       String   @id @default(uuid())\n  userId   String\n  endpoint String   @unique\n  p256dh   String   // public key\n  auth     String   // auth secret\n  deviceName String?  // e.g. \"Chrome on iPhone\"\n  isActive Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"push_subscriptions\")\n}\n\n// ─── Refund & Dispute ────────────────────────────────────────────────────────\n\nenum RefundStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  PROCESSED\n}\n\nenum RefundReason {\n  DAMAGED\n  NOT_RECEIVED\n  WRONG_ITEM\n  NOT_AS_DESCRIBED\n  CHANGED_MIND\n  OTHER\n}\n\nmodel Refund {\n  id          String       @id @default(uuid())\n  orderId     String\n  storeId     String\n  amount      Float\n  reason      RefundReason\n  description String?\n  status      RefundStatus @default(PENDING)\n  gatewayRef  String?      // gateway refund ID\n  processedAt DateTime?\n  adminNote   String?\n  photos      String[]     @default([])\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  order       Order        @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  store       Store        @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([orderId])\n  @@index([storeId])\n  @@map(\"refunds\")\n}\n\n// ─── Customer Accounts ───────────────────────────────────────────────────────\n\nmodel CustomerAccount {\n  id            String    @id @default(uuid())\n  storeId       String\n  email         String\n  name          String\n  phone         String?\n  passwordHash  String\n  emailVerified Boolean   @default(false)\n  verifyToken   String?\n  resetToken    String?\n  resetExpiry   DateTime?\n  refreshToken  String?\n  defaultAddress Json?\n  savedAddresses Json[]   @default([])\n  wishlist       String[] @default([]) // productIds\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  @@unique([storeId, email])\n  @@index([storeId])\n  @@map(\"customer_accounts\")\n}\n\n// ─── Wishlist ────────────────────────────────────────────────────────────────\n\nmodel Wishlist {\n  id         String   @id @default(uuid())\n  storeId    String\n  email      String\n  productId  String\n  createdAt  DateTime @default(now())\n\n  @@unique([storeId, email, productId])\n  @@index([storeId, email])\n  @@map(\"wishlists\")\n}\n\n// ─── Gift Card ───────────────────────────────────────────────────────────────\n\nmodel GiftCard {\n  id          String    @id @default(uuid())\n  storeId     String\n  code        String    @unique\n  balance     Float\n  initialAmount Float\n  currency    String    @default(\"USD\")\n  isActive    Boolean   @default(true)\n  purchasedBy String?   // email\n  assignedTo  String?   // email\n  expiresAt   DateTime?\n  note        String?\n  redeemedAmount Float  @default(0)\n  usages      GiftCardUsage[]\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  store       Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([code])\n  @@map(\"gift_cards\")\n}\n\nmodel GiftCardUsage {\n  id         String   @id @default(uuid())\n  giftCardId String\n  orderId    String\n  amount     Float\n  createdAt  DateTime @default(now())\n\n  giftCard   GiftCard @relation(fields: [giftCardId], references: [id], onDelete: Cascade)\n\n  @@index([giftCardId])\n  @@map(\"gift_card_usages\")\n}\n\n// ─── Funnel Analytics ────────────────────────────────────────────────────────\n\nmodel FunnelEvent {\n  id        String   @id @default(uuid())\n  storeId   String\n  sessionId String\n  event     String   // \"view\" | \"add_to_cart\" | \"checkout_start\" | \"purchase\"\n  productId String?\n  orderId   String?\n  value     Float?\n  meta      Json?\n  ip        String?\n  userAgent String?\n  createdAt DateTime @default(now())\n\n  @@index([storeId])\n  @@index([sessionId])\n  @@index([event])\n  @@index([createdAt])\n  @@map(\"funnel_events\")\n}\n\n// ─── UTM / Traffic Source ────────────────────────────────────────────────────\n\nmodel UtmSession {\n  id         String   @id @default(uuid())\n  storeId    String\n  sessionId  String\n  source     String?\n  medium     String?\n  campaign   String?\n  term       String?\n  content    String?\n  landingPage String?\n  referrer   String?\n  converted  Boolean  @default(false)\n  orderId    String?\n  orderValue Float?\n  createdAt  DateTime @default(now())\n\n  @@unique([storeId, sessionId])\n  @@index([storeId])\n  @@index([source])\n  @@map(\"utm_sessions\")\n}\n\n// ─── API Keys (store owner) ─────────────────────────────────────────────────\n\nmodel ApiKey {\n  id          String    @id @default(uuid())\n  storeId     String\n  name        String\n  keyHash     String    @unique  // SHA-256 of actual key\n  keyPrefix   String             // first 8 chars for display\n  permissions String[]  @default([]) // [\"orders:read\",\"products:write\",...]\n  isActive    Boolean   @default(true)\n  lastUsedAt  DateTime?\n  expiresAt   DateTime?\n  createdAt   DateTime  @default(now())\n\n  store       Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([keyHash])\n  @@map(\"api_keys\")\n}\n\n// ─── Store Backup ────────────────────────────────────────────────────────────\n\nmodel StoreBackup {\n  id        String   @id @default(uuid())\n  storeId   String\n  fileName  String\n  fileUrl   String\n  fileSize  Int?     // bytes\n  status    String   @default(\"PENDING\") // PENDING | READY | FAILED\n  createdAt DateTime @default(now())\n\n  store     Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@map(\"store_backups\")\n}\n\n// ─── Outgoing Webhooks (store owner) ────────────────────────────────────────\n\nmodel StoreWebhook {\n  id        String   @id @default(uuid())\n  storeId   String\n  url       String\n  events    String[] // [\"order.created\",\"order.paid\",\"product.updated\",...]\n  secret    String\n  isActive  Boolean  @default(true)\n  lastFiredAt DateTime?\n  failCount  Int     @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  store      Store            @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  deliveries WebhookDelivery[]\n\n  @@index([storeId])\n  @@map(\"store_webhooks\")\n}\n\nmodel WebhookDelivery {\n  id         String   @id @default(uuid())\n  webhookId  String\n  event      String\n  payload    Json\n  statusCode Int?\n  response   String?\n  success    Boolean  @default(false)\n  createdAt  DateTime @default(now())\n\n  webhook StoreWebhook @relation(fields: [webhookId], references: [id], onDelete: Cascade)\n\n  @@index([webhookId])\n  @@map(\"webhook_deliveries\")\n}\n\n// ─── Flash Sale ──────────────────────────────────────────────────────────────\n\nmodel FlashSale {\n  id          String   @id @default(uuid())\n  storeId     String\n  name        String\n  discountPct Float\n  productIds  String[]\n  startsAt    DateTime\n  endsAt      DateTime\n  isActive    Boolean  @default(true)\n  bannerText  String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  store       Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@map(\"flash_sales\")\n}\n\n// ─── Return / RMA ────────────────────────────────────────────────────────────\n\nenum ReturnStatus {\n  REQUESTED\n  APPROVED\n  REJECTED\n  RECEIVED\n  REFUNDED\n}\n\nmodel ReturnRequest {\n  id          String       @id @default(uuid())\n  orderId     String\n  storeId     String\n  customerEmail String\n  reason      String\n  description String?\n  photos      String[]     @default([])\n  status      ReturnStatus @default(REQUESTED)\n  trackingNumber String?\n  adminNote   String?\n  resolvedAt  DateTime?\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  order       Order        @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  store       Store        @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([orderId])\n  @@index([storeId])\n  @@map(\"return_requests\")\n}\n\n// ─── Subscription Products ───────────────────────────────────────────────────\n\nmodel ProductSubscription {\n  id            String   @id @default(uuid())\n  storeId       String\n  productId     String\n  customerEmail String\n  interval      String   // \"weekly\" | \"monthly\" | \"quarterly\"\n  intervalCount Int      @default(1)\n  price         Float\n  currency      String   @default(\"USD\")\n  discount      Float    @default(0) // % off for subscribing\n  status        String   @default(\"ACTIVE\") // ACTIVE | PAUSED | CANCELLED\n  nextBillingAt DateTime\n  stripeSubId   String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  @@index([storeId])\n  @@index([customerEmail])\n  @@map(\"product_subscriptions\")\n}\n\n// ─── Cohort Analytics ────────────────────────────────────────────────────────\n\nmodel CohortData {\n  id        String   @id @default(uuid())\n  storeId   String\n  cohortMonth String  // \"2025-01\"\n  totalCustomers Int @default(0)\n  day30Return    Int @default(0)\n  day60Return    Int @default(0)\n  day90Return    Int @default(0)\n  calculatedAt   DateTime @default(now())\n\n  @@unique([storeId, cohortMonth])\n  @@index([storeId])\n  @@map(\"cohort_data\")\n}\n\n// ─── KAI Chat History ─────────────────────────────────────────────────────────\n\nmodel KaiConversation {\n  id        String       @id @default(uuid())\n  userId    String\n  title     String       @default(\"New Chat\")\n  createdAt DateTime     @default(now())\n  updatedAt DateTime     @updatedAt\n  messages  KaiMessage[]\n\n  user      User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"kai_conversations\")\n}\n\nmodel KaiMessage {\n  id             String          @id @default(uuid())\n  conversationId String\n  role           String          // \"user\" | \"assistant\"\n  content        String          @db.Text\n  action         String?\n  createdAt      DateTime        @default(now())\n\n  conversation   KaiConversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  @@index([conversationId])\n  @@map(\"kai_messages\")\n}\n\n\nmodel StoreIntegration {\n  id           String    @id @default(cuid())\n  storeId      String\n  store        Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  provider     String\n  email        String?\n  password     String?\n  accessToken  String?   @db.Text\n  refreshToken String?\n  expiresAt    DateTime?\n  isActive     Boolean   @default(true)\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  @@unique([storeId, provider], name: \"storeId_provider\")\n  @@index([storeId])\n}\n\nmodel WaitlistEntry {\n  id           String   @id @default(cuid())\n  name         String\n  email        String   @unique\n  whatsapp     String?\n  spotNumber   Int      @unique\n  referralCode String   @unique\n  referredBy   String?\n  source       String?\n  ipHash       String?\n  confirmed    Boolean  @default(false)\n  createdAt    DateTime @default(now())\n\n  @@index([email])\n  @@index([referralCode])\n  @@index([spotNumber])\n}\n\nmodel Bundle {\n  id              String   @id @default(uuid())\n  storeId         String\n  store           Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  name            String\n  productIds      String[]\n  discountPercent Float    @default(10)\n  bundlePrice     Float?\n  originalPrice   Float?\n  active          Boolean  @default(true)\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n}\n\nmodel GroupBuy {\n  id              String        @id @default(uuid())\n  storeId         String\n  store           Store         @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  productId       String\n  product         Product       @relation(fields: [productId], references: [id])\n  title           String\n  description     String?\n  groupPrice      Float\n  originalPrice   Float\n  minMembers      Int\n  endsAt          DateTime\n  active          Boolean       @default(true)\n  members         GroupBuyMember[]\n  createdAt       DateTime      @default(now())\n}\n\nmodel GroupBuyMember {\n  id          String   @id @default(uuid())\n  groupBuyId  String\n  groupBuy    GroupBuy @relation(fields: [groupBuyId], references: [id], onDelete: Cascade)\n  name        String\n  email       String\n  paid        Boolean  @default(false)\n  createdAt   DateTime @default(now())\n}\n\nmodel Milestone {\n  id        String   @id @default(uuid())\n  storeId   String\n  store     Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  type      String\n  title     String\n  message   String\n  cta       Json?\n  seen      Boolean  @default(false)\n  createdAt DateTime @default(now())\n}\n\nmodel ContactMessage {\n  id        String   @id @default(uuid())\n  name      String\n  email     String\n  subject   String   @default(\"general\")\n  message   String\n  status    String   @default(\"new\")\n  createdAt DateTime @default(now())\n}\n\nmodel Referral {\n  id          String   @id @default(uuid())\n  userId      String   @unique\n  user        User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  code        String   @unique\n  clicks      Int      @default(0)\n  signups     Int      @default(0)\n  conversions Int      @default(0)\n  earned      Float    @default(0)\n  pending     Float    @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n"};
let n=0;
for(const [rel,content] of Object.entries(files)){
  const p=rel.replace(/\//g,path.sep);
  fs.mkdirSync(path.dirname(p),{recursive:true});
  fs.writeFileSync(p,content,'utf8');
  console.log('OK',rel.split('/').slice(-2).join('/'));n++;
}
console.log('Written:',n,'files');
try{
  execSync('git add .',{stdio:'inherit'});
  const st=execSync('git status --short',{encoding:'utf8'}).trim();
  if(st){
    execSync('git commit -m "fix: Complete audit - nav-level endpoint fix, billing BOM removed, auth.refresh wired, JSX in .ts fixed, tsconfig clean"',{stdio:'inherit'});
    execSync('git push origin main',{stdio:'inherit'});
    console.log('Pushed. Deploying.');
  }else{console.log('Nothing to commit');}
}catch(e){console.log('Git error:',e.message);}
